    wtm_access: { title: "L'ascensore della sede", text: "Dicono che a volte si blocca.", o: ["Sopralluogo con chi usa la carrozzina", "Chiedi le chiavi del montacarichi"], ignore: "Si spera che funzioni.", tipT: "L'accessibilità si verifica prima", tipD: "Percorsi, ascensori, bagni, palco: un sopralluogo con chi li usa davvero scopre tutto in un'ora." },
