    hk_food: { title: "Si mangia?", text: "Sedici ore, novanta persone.", o: ["Pizza a mezzanotte e colazione", "Snack e macchinette"], ignore: "Ognuno porta qualcosa.", tipT: "Cibo, Wi-Fi e corrente", tipD: "Le tre cose che non possono mancare a un hackathon, secondo MLH. Ordina sui numeri confermati." },
    hk_rest: { title: "E chi dorme?", text: "Alle 4 qualcuno crollerà.", o: ["Sala riposo con brandine", "Si dorme sui pouf"], ignore: "Pouf e giacche.", tipT: "La notte va organizzata", tipD: "Una sala riposo silenziosa e i turni per lo staff: chi crolla alle 4 non presenta alle 9." },
    hk_rules: { title: "Regolamento e premi", text: "I criteri della giuria non sono scritti.", o: ["Criteri pubblici fin dall'inizio", "Decide la giuria sul momento"], ignore: "Si vedrà alla fine.", tipT: "Regole chiare, verdetto accettato", tipD: "Criteri pubblici dal kickoff evitano ricorsi e malumori alla premiazione." },
