    sede: { title: "Serve una sede da 170 posti", text: "La data va bloccata adesso.", o: ["Aula Magna dell'università", "Centro congressi"], ignore: "Un ripiego all'ultimo, rete ballerina.", tipT: "La sede si cerca mesi prima", tipD: "GDG Spain ci ha messo tre mesi. Le università sono partner naturali, ma la rete va verificata: 30 Mbps ogni 100 persone." },
    sponsor: { title: "1.500 € per la lista email", text: "Uno sponsor vuole gli indirizzi degli iscritti.", o: ["Stand e logo, niente dati", "Accetta, servono i soldi"], ignore: "Lo sponsor va altrove.", tipT: "I dati non sono merce", tipD: "Girare le email degli iscritti richiede il loro consenso (GDPR). Agli sponsor si offrono visibilità e 5-10 minuti sul palco." },
    team: { title: "Il bus factor è 1", text: "Se ti trasferisci, il chapter si ferma con te.", o: ["Recluta un co-organizer", "Coinvolgi la GDG on Campus"], ignore: "Tutto sulle tue spalle.", tipT: "Un team piccolo ma vero", tipD: "Un evento grande regge con 3-9 persone e un responsabile per area. Chi fa tutto da solo si brucia." },
    promo: { title: "Le iscrizioni sono ferme", text: "Mancano otto settimane.", o: ["Inviti: università, meetup, chapter", "Post sponsorizzato"], ignore: "Crescono da sole, poco.", tipT: "Tre volte prima di iscriversi", tipD: "Si promuove da due mesi prima: una persona deve vedere l'evento circa tre volte." },
