    coc: { title: "Il Code of Conduct basta?", text: "È linkato. Nessuno sa cosa fare se arriva una segnalazione.", o: ["Due referenti formati", "Il link basta"], ignore: "Il link resta lì.", tipT: "Il CoC è una procedura", tipD: "Staff riconoscibile, ogni segnalazione ascoltata. A PyCon 2019 ne sono arrivate 13." },
    diversita: { title: "Nove speaker, tutti uomini", text: "Te lo fa notare un'iscritta.", o: ["Cerca speaker diverse", "Sarà per l'anno prossimo"], ignore: "La lineup resta così.", tipT: "La diversità si costruisce prima", tipD: "Molti DevFest si danno obiettivi espliciti: il Nord America 2018 puntava al 35% di speaker donne." },
    accesso: { title: "Tre gradini, nessuna rampa", text: "Una persona in carrozzina chiede se potrà entrare.", o: ["Rampa e percorsi segnalati", "Vedremo sul momento"], ignore: "Nessuno risponde.", tipT: "Accessibile si progetta", tipD: "Ingresso senza gradini, microfoni per le domande, una stanza tranquilla: la guida SIGACCESS è una checklist." },
    swag: { title: "Le magliette arrivano lunedì", text: "Il DevFest è sabato.", o: ["Spedizione express", "Pazienza, adesivi"], ignore: "Niente magliette.", tipT: "Il gadget conta meno del previsto", tipD: "Gadget e magliette costano, arrivano in ritardo e non trattengono nessuno: meglio un buon pranzo." },
