    promotalk: { title: "Un talk che è una televendita", text: "Un membro vuole presentare il suo prodotto.", o: ["Proponi un talk tecnico", "Accetta (paga 200 €)"], ignore: "Il talk passa così.", tipT: "Niente vendite dal palco", tipD: "I GDG sono non profit e indipendenti: niente formazione a pagamento né vendite travestite da talk." },
    catering: { title: "Quanti pranzi ordinare?", text: "Il ristoratore vuole il numero entro venerdì.", o: ["Il 75-80% dei presenti, confermato", "Pizza chiamata sul momento"], ignore: "Si improvvisa.", tipT: "Ordina per chi viene davvero", tipD: "Negli eventi gratuiti manca dal 28% al 50% degli iscritti. Il cibo si ordina per il 75-80% delle presenze attese." },
