    checkin: { title: "150 persone in mezz'ora", text: "Metà arriva tra le 9:00 e le 9:30.", o: ["QR e badge prestampati", "Lista stampata"], ignore: "Lista stampata.", tipT: "Il check-in è il primo ricordo", tipD: "Il check-in sulla piattaforma è anche il numero ufficiale delle presenze. 1.000 persone con 15 volontari: un'ora e mezza." },
    badgekit: { title: "E chi non si è iscritto?", text: "Arriverà. Sempre.", o: ["Badge extra nella Scatola", "Si scrive a mano"], ignore: "Nessun badge extra.", tipT: "Chi arriva senza iscrizione", tipD: "Una scorta di badge vuoti e pennarelli evita la coda nella coda." },
    speakercare: { title: "Gli speaker sanno dove andare?", text: "Arrivano da tre regioni.", o: ["Mail con mappa e contatto", "C'è il gruppo WhatsApp"], ignore: "Si arrangiano.", tipT: "Speaker accolti, talk puntuali", tipD: "Agli speaker si chiede di arrivare 15-20 minuti prima, con un riferimento e una mappa." },
    riserva: { title: "E se uno speaker salta?", text: "Succede sempre. Non sai quale.", o: ["Un talk di riserva pronto", "Lightning talk jolly"], ignore: "Si vedrà.", tipT: "Metti in conto un forfait", tipD: "Almeno uno speaker non si presenta. La riserva va preparata come gli altri." },
    overbooking: { title: "Più iscritti che posti", text: "Chiudere o tenere aperto?", o: ["1,5 volte i posti + lista d'attesa", "Tieni aperto"], ignore: "Restano aperte.", tipT: "Overbooking con giudizio", tipD: "Per un evento gratuito si registra 1,5-1,7 volte la capienza. Una cauzione rimborsabile alza le presenze." },
    antincendio: { title: "Manutenzioni in sede?", text: "Nessuno ha chiesto il calendario.", o: ["Chiedi alla sede", "Che vuoi che succeda"], ignore: "Nessuno chiede.", tipT: "Il calendario della sede", tipD: "Prove d'allarme, pulizie, chiusure: la sede ha un calendario che non conosci finché non lo chiedi." },
    stampa: { title: "Il giornale locale vuole venire", text: "Cercano qualcuno da intervistare.", o: ["Prepara un referente", "Se viene, vedremo"], ignore: "Vedremo.", tipT: "La stampa è un'occasione", tipD: "Un articolo locale porta iscritti e sponsor all'edizione dopo: serve qualcuno pronto a parlare." },
    reminder: { title: "Mancano sette giorni", text: "Molti iscritti se ne sono dimenticati.", o: ["Promemoria: «non vieni? libera il posto»", "Una storia su Instagram"], ignore: "Nessun promemoria.", tipT: "I promemoria riempiono le sale", tipD: "Promemoria personali riducono le assenze. I biglietti arrivano nelle ultime 72 ore: chiudi in tempo per il catering." },
    runofshow: { title: "Chi fa cosa, minuto per minuto?", text: "C'è il programma. La scaletta dello staff no.", o: ["Scaletta e un responsabile per area", "Si improvvisa"], ignore: "Nessuna scaletta.", tipT: "Un responsabile per area", tipD: "Le linee di comunicazione crescono come N(N-1)/2: una scaletta condivisa evita che tutto passi da una persona." },
