    calendario: { title: "Stesso giorno del DevFest vicino", text: "Lo scopri da un post su LinkedIn.", o: ["Coordinatevi: speaker e promo", "Vinca il migliore"], ignore: "Il pubblico si divide.", tipT: "Il calendario è di tutti", tipD: "Nel 2025 tre DevFest italiani si sono tenuti lo stesso giorno. Un calendario condiviso tra chapter evita il conflitto." },
    stanchezza: { title: "Non dormi da giorni", text: "Lavoro, DevFest, lavoro, DevFest.", o: ["Fermati un weekend", "Stringi i denti"], ignore: "Stringi i denti.", tipT: "Il burnout è il vero rischio", tipD: "«Più lavoro che divertimento», scrive chi l'ha fatto per cinque anni. Strange Loop ha chiuso per esaurimento." },
    cani: { title: "La sede confina con un parco", text: "Cani a spasso ovunque, porte aperte.", o: ["Un volontario all'ingresso", "Sono carini, dai"], ignore: "Porte aperte.", tipT: "Chi presidia l'ingresso", tipD: "L'ingresso è il punto da cui entra tutto: persone, fornitori, imprevisti. Qualcuno deve guardarlo." },
    m_pizza: { title: "Quaranta pizze o sessanta?", text: "Iscritti 70, posti 50.", o: ["Ordina per i presenti, a orario fisso", "Le chiamiamo alle 20"], ignore: "Si chiamano alle 20.", tipT: "Pizza per chi c'è", tipD: "Un meetup costa 100-250 € di cibo al mese. Si ordina per le presenze attese, non per gli iscritti." },
    m_porta: { title: "Chi apre la sede alle 18?", text: "Le chiavi le ha il custode. Che finisce alle 17.", o: ["Accordati e ritira le chiavi", "Speriamo resti"], ignore: "Tutti fuori ad aspettare.", tipT: "Ogni sede ha un custode", tipD: "Dodici sedi l'anno vogliono dire dodici custodi da conoscere per nome." },
