    m_speaker: { title: "Lo speaker vuole 90 minuti", text: "Lo slot è di 40.", o: ["Cartello del tempo e moderatore", "Lasciamolo parlare"], ignore: "Parlerà quanto vuole.", tipT: "I talk sforano", tipD: "I cambi di 5 minuti non bastano mai: serve qualcuno che tenga il tempo." },
